[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$MessageId,[Parameter(Mandatory=$true)][string]$WorkerId,[string]$ResultPath='')
Import-Module (Join-Path $PSScriptRoot 'queue.psm1') -Force -DisableNameChecking
Assert-SafeId $MessageId 'MessageId';Assert-SafeId $WorkerId 'WorkerId';$q=Get-QueueRoot;$src=Join-Path $q "processing/$MessageId.json";if(-not(Test-Path -LiteralPath $src)){throw 'processing message not found'};$m=Read-QueueJson $src;$s=Read-State $MessageId;if(-not $s -or $s.status -ne 'PROCESSING' -or [string]$s.claimedBy -ne $WorkerId){throw 'worker does not own lease'}
$resultDigest='';if($ResultPath){if(-not(Test-Path -LiteralPath $ResultPath -PathType Leaf)){throw 'ResultPath missing'};$sha=[Security.Cryptography.SHA256]::Create();try{$resultDigest=([BitConverter]::ToString($sha.ComputeHash([IO.File]::ReadAllBytes($ResultPath)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$dest=Join-Path $q "completed/$MessageId.json";Move-Item -LiteralPath $src -Destination $dest -ErrorAction Stop;$now=UtcNow;$receipt=[ordered]@{schema='pmcro.queue.receipt/v1';messageId=$MessageId;messageDigest=[string]$m.contentDigest;dedupeDigest=[string]$m.dedupeDigest;workerId=$WorkerId;attempt=[int]$s.attempt;completedAt=Iso $now;resultDigest=$resultDigest;sourceAgent=[string]$m.sourceAgent;targetAgent=[string]$m.targetAgent;trailId=[string]$m.trailId}
$rpath=Join-Path $q "receipts/$MessageId.json";if(Test-Path -LiteralPath $rpath){throw 'receipt already exists'};Write-JsonAtomic $rpath $receipt;$s.status='COMPLETED';$s.claimedBy='';$s.leaseUntil='';$s.updatedAt=Iso $now;Write-State $MessageId $s;Write-Output "ACKED $MessageId"
